                visited.add(node)
                ans.append(node)
            if toVisit[node] == len(self.G[node]):
                if node == self.king:
                    return 
                else:
                    return dfs(self.parent[node], ans)
            else:
                toVisit[node] +=1
                dfs(self.G[node][toVisit[node]-1], ans)
        dfs(self.king, ans)
        return ans

