        order = []
        stack = [self.kingName]
        while stack:
            name = stack.pop()
            if name in self.parent2son:
                next = []
                for son in self.parent2son[name]:
                    next.insert(0, son)
                stack = stack + next
            if name not in self.deadset:
                order.append(name)
        return order


