            res = []
            for nr, nc in [[r+1, c], [r, c+1], [r-1, c], [r, c-1]]:
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != '#':
                    res.append((nr, nc))
            return res

        def connected(p, q, box):
            queue = collections.deque([p])
            seen = set()
            while queue:
                node = queue.popleft()
                for nr, nc in nxt(node):
                    if (nr, nc) != box:
                        if (nr, nc) == q:
                            return True
                        if (nr, nc) not in seen:
