                elif grid[i][j] == 'S':
                    player = [i, j]

        i, j = box
        x, y = player
        q = collections.deque()
        q.append((i, j, x, y))  # i, j is where the box is, x, y is where the player is
        visited = set()
        visited.add((i, j, x, y))

        step = 0
        dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]]
        while q:
            size = len(q)
            for _ in range(size):
                i, j, x, y = q.popleft()
                if grid[i][j] == 'T':
                    return step

                for di, dj in dirs:
                    i2 = i + di
                    j2 = j + dj
                    if i2 < 0 or i2 >= self.m or j2 < 0 or j2 >= self.n or (i2, j2, i, j) in visited or grid[i2][j2] == '#' or not self.helper(grid, x, y, i, j, i - di, j - dj):
                        continue

