        max_A = max(A)
        if max_A <= 0:
            return max_A
        max_sum = 0
        cur_sum = 0
        for i in range(len(A)):
            cur_sum = max(cur_sum, 0) + A[i]
            max_sum = max(max_sum, cur_sum)
        if len(A) <= 2:
            return max_sum

        right_sum = A[-1]
        right_max = [A[-1]]
