    def __init__(self):
        self.parent={}
        self.size={}

    def find(self,x):
        if x!=self.parent[x]:
            self.parent[x]=self.find(self.parent[x])
        return self.parent[x]

    def union(self,x,y):
        xp,yp=self.find(x),self.find(y)
        if xp==yp:
