    max_ = 1
    for num in nums:
      if num == 1:
        continue
      pDs = self.primeDivisors(num)
      pD0 = pDs.pop()
      UF.add(pD0)
      for pD in pDs:
        UF.add(pD)
        UF.union(pD0, pD)
      count = UF.incCount(pD0)
      max_ = max(max_, count)
    return max_

  def primeDivisors(self, num: int):
      x = num

      pDs = set()

      if x % 2 == 0:
          pDs.add(2)
          while x % 2 == 0:
              x >>= 1

      if x % 3 == 0:
          pDs.add(3)
          while x % 3 == 0:
              x //= 3

      div = 5
      d2 = True
      while x >= div*div:
          if x % div == 0:
              pDs.add(div)
              while x % div == 0:
                  x //= div
          div += 2 if d2 else 4
          d2 = not d2

      if x > 1:
        pDs.add(x)

      return pDs
