class DSU:
    def __init__(self, n):
        self.store = list(range(n))

    def find(self, i):
        assert 0 <= i < len(self.store)

        if i != self.store[i]:
            self.store[i] = self.find(self.store[i])

        return self.store[i]

    def union(self, x, y):
        x_idx = self.find(x)
        y_idx = self.find(y)

        self.store[y_idx] = x_idx


