    def __init__(self, size):
        self.indexes = {i:i for i in range(size)}
        self.sizes = {i:1 for i in range(size)}

    def root(self, i):
        node = i
        while i!=self.indexes[i]:
            i = self.indexes[i]

        while node!=i:
            nnode = self.indexes[node]
            self.indexes[node] = i
            node = nnode
        return i

