import math

class UnionFind:

    def __init__(self , size):
        self.id = [i for i in range(size)]

    def find(self , p):

        root = p
        while root != self.id[root]:
            root = self.id[root]

        while p != root:
            nxt = self.id[p]
            self.id[p] = root
            p = nxt

        return root


    def unify(self , p , q):

        root1 = self.find(p)
        root2 = self.find(q)
        if root1 == root2 : return 

        self.id[root2] = root1








