class UnionFind:
    def __init__(self):
        self.parents = {}

    def connect(self, a, b):
        if a not in self.parents:
            self.parents[a] = a

        if b not in self.parents:
            self.parents[b] = b

        root = self.root(b)
        self.parents[self.root(a)] = root
        return root

    def root(self, a):
        if a not in self.parents:
            self.parents[a] = a
            return a

        if a == self.parents[a]:
            return a

        self.parents[a] = self.root(self.parents[a])

        return self.parents[a]


class Sieve:
    def __init__(self, max_n):
        self.primes = self._compute_primes(max_n)
        self.factors = {p: [p] for p in self.primes}
        # self.factors = {}

    def _compute_primes(self, max_n):
        primes = list()
        sieve = [True] * (max_n+1)
        for prime in range(2, max_n+1):
            if not sieve[prime]:
                continue

            primes.append(prime)

            for j in range(prime+prime, max_n+1, prime):
                sieve[j] = False

        return primes

    @lru_cache(maxsize=MAX_N)
    def factorize(self, n):
        if n in self.factors:
            return self.factors[n]

        self.factors[n] = factors = set()
        work = n
        for prime in self.primes:
            if work < prime:
                break

            if work % prime == 0:
                factors.add(prime)
                work //= prime

                factors.update(self.factorize(work))
                break

        return factors


class Graph:
    def __init__(self):
        self.adj = {}
        self.factors = set()
        self.values = set()

