class DSU:
    def __init__(self, N):
        self.p = list(range(N))

    def find(self, x):
        n = self.p[x]
        while n >= 0 and self.p[n] != n:
            n = self.p[n]
        root = n
        # compact
        n = x
        while n >= 0 and self.p[n] != n:
            t = self.p[n]
            self.p[n] = root
            n= t
        return root

