    def __init__(self, n):
        self.parants = [0] * n
        self.rank = [0] * n

        # self is a distinct group
        for i in range(n):
            self.parants[i] = i

    def find(self, x):
        if x != self.parants[x]:
            self.parants[x] = self.find(self.parants[x])
        return self.parants[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)

        # already in same group, no need to merge again
        if px == py: return False

        if self.rank[px] < self.rank[py]:
            self.parants[px] = py
        elif self.rank[px] > self.rank[py]:
            self.parants[py] = px
        else:
            self.parants[py] = px
            self.rank[py] += 1

