class Solution:
    def largestComponentSize(self, A: List[int]) -> int:
        union = DisjoinSet(max(A))
        for a in A:
            for factor in range(2, int(sqrt(a)) + 1):
                if a % factor == 0:
                    union.union(a, factor)
                    union.union(a, a // factor)
