", "class UF:
    def __init__(self, n):
        self.arr = list(range(n + 1))
        self.rank = [1] * (n + 1)

    def root(self, x):
        curr = x

        while curr != self.arr[curr]:
            curr = self.arr[curr]
        return curr

    def union(self, x, y):
        root_x = self.root(x)
        root_y = self.root(y)

        rank_x = self.rank[root_x]
        rank_y = self.rank[root_y]

        if rank_x >= rank_y:
            self.arr[root_y] = root_x
            self.rank[root_x] += rank_y
        else:
            self.arr[root_x] = root_y
            self.rank[root_y] += rank_x

