    def __init__(self, n):
        self.roots = list(range(n + 1))
        self.cnts = [1] * (n + 1)

    def find(self, x):
        if self.roots[x] != x:
            self.roots[x] = self.find(self.roots[x])
        return self.roots[x]

    def union(self, x, y):
        rx = self.find(x)
        ry = self.find(y)
        if rx == ry:
            return False
        if self.cnts[rx] >= self.cnts[ry]:
            self.roots[ry] = rx
            self.cnts[rx] += self.cnts[ry]
            self.cnts[ry] = 0
        else:
            self.roots[rx] = ry
            self.cnts[ry] += self.cnts[rx]
            self.cnts[rx] = 0
        return True

