class UF:
    def __init__(self, n):
        self.uf = [i for i in range(n)]
        self.size = [1] * n

    def find(self, u):
        while u != self.uf[u]:
            self.uf[u] = self.uf[self.uf[u]]
            u = self.uf[u]
