    def qs(self, nums, start, end):
        if start >= end:
            return

        pivot = nums[(start+end) // 2]

        left, right = start, end

        while left <= right:
            while left <= right and nums[left] < pivot:
                left += 1

            while left <= right and nums[right] > pivot:
                right -= 1

            if left <= right:
