class Solution:
    def numSubseqNormal(self, nums: List[int], target: int) -> int:
        nums = sorted(nums)
        n = len(nums)
        count = 0
        mod = 10 ** 9 + 7
        for i in range(n):
            for j in range(i, n):
                if (nums[i] + nums[j]) <= target:
                    if i == j:
                        count += 1
                    else:
                        count += pow(2, j - i - 1)
                    count %= mod
        return count

    # 加强
    def numSubseq1(self, nums: List[int], target: int) -> int:
        nums = sorted(nums)
        n = len(nums)
        count = 0
        mod = 10 ** 9 + 7
        for i in range(n):
            j = i
            while j < n and (nums[i] + nums[j]) <= target:
                j += 1
            if i == j:
                if (nums[i] + nums[j]) <= target:
                    count += 1
            elif (nums[i] + nums[j - 1]) <= target:  # 防止第一个数就超过
                count += pow(2, j - i - 1) % mod
        return count % mod

    def findLast(self, nums, start, end, target):
        first = nums[start]
        while start <= end:
            mid = int((start + end) / 2)
            second = nums[mid]
            if first + second > target:
                end = mid - 1
            elif first + second < target:
                start = start + 1
            elif first + second == target:
                start = start + 1
        return start

    def numSubseq12(self, nums: List[int], target: int) -> int:
        nums = sorted(nums)
        n = len(nums)
        count = 0
        mod = 10 ** 9 + 7
        pow_map = [1 for _ in range(n)]
        for i in range(1, n):
            pow_map[i] = (2 * pow_map[i - 1]) % mod

        for i in range(n):
            if nums[i] > target:
                    break
            j = self.findLast(nums, i, n - 1, target)
            if i == j:
