        def countandsum(target):
            i=0
            cur=0
            sum1=0
            total=0
            count=0
            for j in range(n):
                cur+=nums[j]
                sum1+=nums[j]*(j-i+1)
                while cur>target:
                    sum1-=cur
                    cur-=nums[i]
                    i+=1
                count+=j-i+1
                total+=sum1
