            node = q.popleft()
            ans.append(node)
            for nei in rgraph[node]: 
                if out_degree[nei] == 0: 
                    continue
                out_degree[nei] -= 1
                if out_degree[nei] == 0: 
                    q.append(nei)
        ans.sort()
        return ans




