        return self.helper(d,f,target,dic)

    def helper(self, d2, f2, target2,dic):
        if target2 == 0 and d2 == 0:
            return 1
        if (d2,f2,target2) in dic:
            return dic[(d2,f2,target2)]
        if target2 < d2 or d2*f2 < target2:
            dic[(d2,f2,target2)] = 0
            return 0
        elif d2 == 1:
            dic[(d2,f2,target2)] = 1
