    return total

def count(balls, balance, a, b, i):
    c = balls[i]

    upper = min(c, a)
    lower = max(c - b, 0)

    tempBalance = balance

    total = 0

    for j in range(lower, upper + 1):
        balance = tempBalance
        if j == 0:
            balance -= 1
        if j == c:
            balance += 1
        if i == len(balls) - 1:
            if balance == 0:
                return 1
            else:
                return 0
        else:
            total += choose(a, j) * choose(b, c - j) * count(balls, balance, a - j, b - c + j, i + 1)

    return total

