import heapq

class Solution:
  def minJumps(self, arr: List[int]) -> int:
    n = len(arr)
    # priority queue, O(NlogN)
    d = defaultdict(set)
    for i, x in enumerate(arr):
      d[x].add(i)
    q, s = [(0, 0)], defaultdict(lambda: float('inf'))
    s[0] = 0
    while q:
      m, i = heapq.heappop(q)
      i = -i
      if i - 1 >= 0 and s[i - 1] > m + 1:
        s[i - 1] = m + 1
        heapq.heappush(q, (m + 1, -(i - 1)))
