    path = [n]
    while n != 1:
        if n % 2:
            path.append((n - 1) // 2)
            n = (n - 1) // 2
        else:
            path.append(n // 2)
            n //= 2
    return path


def path_beetwen(a, b):
    p1 = path_to_root(a)
    p2 = path_to_root(b)
    l1 = len(p1)
    l2 = len(p2)
    x = 0
    while x < l2:
        if p2[x] in p1:
            break
        x += 1
    path = p1[:p1.index(p2[x]) + 1] + p2[:x][::-1]
    return path


