from collections import defaultdict


def find_cost(node_1,node_2,intersect_dict):
    new_dict = defaultdict(lambda : 0)
    cost = 0
    while node_1 != 0:
        new_dict[node_1] = 1
        cost+= intersect_dict[node_1]
#        print(node_1,cost)
        node_1 //= 2

    while node_2!=0:
        if new_dict[node_2]:
            cost -= intersect_dict[node_2]
#            print(node_2)
            break
        else:
            new_dict[node_2] = 1
            cost += intersect_dict[node_2]
            node_2 //= 2
#            print(node_2,cost)
    while node_2 != 0:
        node_2 //= 2
        cost -= intersect_dict[node_2]


    return cost


def increase_cost_on_path(node_1,node_2,inc_cost,intersect_dict):
    new_dict = defaultdict(lambda :0)
    while node_1 != 0:
        new_dict[node_1] = 1
        intersect_dict[node_1] += inc_cost
        node_1 //= 2
    while node_2 != 0 :
        if new_dict[node_2]:
            break
        else:
            intersect_dict[node_2] += inc_cost
            node_2//=2

    while node_2 != 0:
        intersect_dict[node_2] -= inc_cost
        node_2 //= 2
    return intersect_dict


