            if i-lv == self.m:
                if lch > lv:
                    seq.append(lch)
                    lv = lch
                else:
                    is_possible = False
                    break
            i += 1
        if not is_possible:
            return False, []
        else:
            return True, seq

    def get_sequence(self):
