def zeta(data, merge):
    """
    （この関数はdataを上書きします）
    Mはモノイド
    data: 2^n -> M
    output: 2^n -> M
    merge: M -> M

    ouput[i] = sum(data[j] for j in range(2^n) if i|j == i)
    """
    n = len(data)
    i = 1
    while i < n:
        j = i
        while j < n:
            data[j] = merge(data[j], data[j&~i])
            j = (j+1)|i
        i <<= 1
    return data


