# 2n+1 is needed as 1-index would be used
tree = [{'round_num':m, 'winner':-1} for _ in range(2*n+1, 0, -1)]

def modify(left, right, pair):
  left += n
  right += n
  while left <= right:
    if isOdd(left):
      tree[left] = pair

    if not isOdd(right):
      tree[right] = pair

    left = int((left+1)/2)
    right = int((right-1)/2)


def query(pos):
  pos += n
  min = 1000000
  winner = -1

  while pos > 0:
    if tree[pos]['round_num'] < min:
      winner = tree[pos]['winner']
      min = tree[pos]['round_num']
    pos >>= 1

  return winner if winner > -1 else 0

rounds = []
for _ in range(m):
  li, ri, xi = invar()
  rounds.append({'left':li, 'right':ri, 'winner':xi})

# iterating input in reverse order
for idx in range(m-1, -1, -1):
  round = rounds[idx]
  # update winner for all the knights in tournament. except for winner itself
  if round['winner'] > 0: modify(round['left'], round['winner']-1, {'round_num': idx, 'winner':round['winner']})
  if round['winner'] < n: modify(round['winner']+1, round['right'], {'round_num': idx, 'winner':round['winner']})

print(*[query(i) for i in range(1, n+1)])
