import queue
class UF(object):
    def __init__(self, n):
        self.arr = list(range(n+1))
        self.rank = [1]*(n+1)

    def root(self, x):
        if self.arr[x] != x:
            self.arr[x] = self.root(self.arr[x])
        return self.arr[x]

    def union(self, x, y):
        root_x = self.root(x)
        root_y = self.root(y)

        if root_x == root_y:
            return 

        rank_x = self.rank[root_x]
        rank_y = self.rank[root_y]

        if rank_x >= rank_y:
            self.rank[root_x] += rank_y
            self.arr[root_y] = root_x
        else:
            self.rank[root_y] += rank_x
            self.arr[root_x] = root_y

